        if (type) { dl[p] = eps; lmodel(&L, type, dl, &Lp); dl[p] = -eps; lmodel(&L, type, dl, &Lm); }
        else { dl[p] = eps; lperturb(&L, e1, e2, dl, &Lp); dl[p] = -eps; lperturb(&L, e1, e2, dl, &Lm); }
