                double X1 = qx - 3.5, Y1 = qy - 3.5;
                int xj = (int)X1, yj = (int)Y1, g8 = (int)((X1 - xj) * 256 + 0.5), g15 = (int)((Y1 - yj) * 32767 + 0.5);
                const v128_t u0 = wasm_i16x8_splat((short)(256 - g8)), u1 = wasm_i16x8_splat((short)g8), U0 = wasm_i16x8_splat((short)(32767 - g15)), U1 = wasm_i16x8_splat((short)g15);
                const uint8_t *q = I1 + yj * w + xj;
                v128_t hprev = kh(q, u0, u1), bxa = wasm_i32x4_splat(0), bya = bxa, ea = bxa;
