#define DET_T0 0         /* tier1m: frames with budget DET_BUDGET0 */
#endif
#ifndef DET_BUDGET0
#define DET_BUDGET0 1000
#endif
#ifndef DET_STRIDE
#define DET_STRIDE 2     /* candidate stride inside a cell (2 = B16) */
#endif
